{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Gefitinib, a close 4-anilinoquinazoline analogue sharing the 3-chloro-4-fluoroanilino group, has ~60% oral bioavailability in humans, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Zongertinib, a structurally related quinazoline-based TKI, was predicted to have 41% oral bioavailability in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Simotinib, another 4-anilinoquinazoline with the same aniline substituent, showed good oral bioavailability in patients, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Afatinib, a 4-anilinoquinazoline EGFR TKI, demonstrated good oral bioavailability in Phase I human studies, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lapatinib, a larger 4-anilinoquinazoline, is reported to have low oral bioavailability; its much lower similarity and distinct solubility-limited structure reduce transferability, but it is the main contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues with direct human bioavailability data (gefitinib ~60%, zongertinib 41%, simotinib good, afatinib good) consistently support F >= 20%. The main low-bioavailability analogue, lapatinib, is less similar and its poor F is driven by larger, poorly soluble substituents not present in the query. The query's moderate size and lipophilicity, despite basic ionization, are compatible with high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "Afatinib's absolute bioavailability in humans is not quantitatively established.",
    "Lapatinib low-bioavailability records are qualitative and not clearly threshold-quantified relative to F < 20%.",
    "Query-specific solubility, permeability, and efflux data are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

